create table if not exists public.parties(id uuid primary key default gen_random_uuid(), leader_character_id uuid not null references public.characters(id), status text not null default 'forming', created_at timestamptz not null default now());
create table if not exists public.party_members(party_id uuid not null references public.parties(id) on delete cascade, character_id uuid not null references public.characters(id), role text not null, joined_at timestamptz not null default now(), primary key(party_id,character_id));
create table if not exists public.echo_profiles(id uuid primary key default gen_random_uuid(), character_id uuid not null references public.characters(id), profile_version integer not null, content_version text not null, role text not null, synced_level integer not null, loadout_snapshot jsonb not null, loadout_hash text not null, preferences jsonb not null default '{}', published_at timestamptz not null default now(), unique(character_id,profile_version));
create table if not exists public.guilds(id uuid primary key default gen_random_uuid(), name text not null unique, owner_account_id uuid not null, level integer not null default 1, xp bigint not null default 0, member_cap integer not null default 30 check(member_cap between 1 and 60), created_at timestamptz not null default now());
create table if not exists public.guild_members(guild_id uuid not null references public.guilds(id) on delete cascade, account_id uuid not null, role text not null default 'member', contribution_xp bigint not null default 0, joined_at timestamptz not null default now(), primary key(guild_id,account_id));
alter table public.parties enable row level security;alter table public.party_members enable row level security;alter table public.echo_profiles enable row level security;alter table public.guilds enable row level security;alter table public.guild_members enable row level security;
create policy "public guild browse" on public.guilds for select using(true);create policy "guild members readable" on public.guild_members for select using(account_id=auth.uid() or exists(select 1 from public.guild_members gm where gm.guild_id=guild_id and gm.account_id=auth.uid()));
create policy "echo profiles readable" on public.echo_profiles for select using(true);
